import numpy as np
from itertools import combinations
tf={'t':t,'t2':t**2,'sqrt':np.sqrt(t),'log':np.log(t),'exp':np.exp(-t),'inv':1/t,'t3':t**3,'logt1':np.log1p(t),'exp2':np.exp(-t/2),'inv2':1/t**2}
pf={'P':P,'P2':P**2,'P3':P**3,'1':np.ones_like(P)}
def test(keys_t,keys_p):
    cols=[];nm=[]
    for a in keys_t:
        for b in keys_p:
            cols.append(tf[a]*pf[b] if a else pf[b]);nm.append((a or '1')+'*'+b)
    X=np.array(cols).T
    c=np.linalg.lstsq(X,dP_dt,rcond=None)[0]
    r=X@c-dP_dt
    return np.mean(r**2)/np.var(dP_dt),nm,c
